import React, { useState, useEffect } from 'react';
import { uploadFile, getFiles, downloadFile, deleteFile } from '../services/api'; // Import delete
import CryptoFlow from '../components/CryptoFlow';
import { Upload, Download, FileText, AlertTriangle, Server, HardDrive, Terminal, Trash2, Activity } from 'lucide-react';

const Dashboard = () => {
  const [files, setFiles] = useState([]);
  const [uploadStep, setUploadStep] = useState(0); 
  const [error, setError] = useState(null);
  const [logs, setLogs] = useState([]); 
  const [selectedFile, setSelectedFile] = useState(null); // For specific file report

  // Toggles
  const [storageMode, setStorageMode] = useState('local');
  const [cryptoMode, setCryptoMode] = useState('hybrid'); // 'hybrid' or 'rsa'

  useEffect(() => {
    fetchFiles();
  }, []);

  const addLog = (msg) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const fetchFiles = async () => {
    try {
      const res = await getFiles();
      setFiles(res.data);
    } catch (err) { console.error("Fetch failed"); }
  };

  const handleDelete = async (id) => {
      if(!window.confirm("Permanently delete this file from the Vault?")) return;
      try {
          await deleteFile(id);
          addLog(`WARN: File ID ${id} deleted from vault.`);
          fetchFiles();
          if (selectedFile?.id === id) setSelectedFile(null);
      } catch (err) {
          setError("Delete failed.");
      }
  };

  const handleUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setError(null);
    setUploadStep(1);
    setLogs([]); 
    setSelectedFile(null); // Clear previous selection
    
    addLog(`INIT: Secure Upload Protocol for ${file.name}`);
    addLog(`MODE: ${cryptoMode === 'hybrid' ? 'Hybrid Post-Quantum (Kyber-512)' : 'Baseline (RSA-2048 Simulation)'}`);

    // Dynamic Animation based on Mode
    if (cryptoMode === 'hybrid') {
        setTimeout(() => { setUploadStep(2); addLog("PQC: Generating Ephemeral Keys..."); }, 600);
        setTimeout(() => { setUploadStep(3); addLog("PQC: Encapsulating Shared Secret..."); }, 1200);
    } else {
        setTimeout(() => { addLog("RSA: Skipping Quantum Key Gen (Baseline Mode)..."); }, 600);
    }
    
    setTimeout(() => { setUploadStep(4); addLog("KDF: Deriving AES-256-GCM Session Key..."); }, 1800);

    try {
      // Send cryptoMode to backend
      const res = await uploadFile(file, cryptoMode); 
      
      setUploadStep(5);
      addLog("AES: Encrypting File Payload...");
      addLog(`PERF: PQC=${res.data.metrics.pqc_encap_ms.toFixed(2)}ms | AES=${res.data.metrics.aes_enc_ms.toFixed(2)}ms`);
      
      setTimeout(() => {
        setUploadStep(0);
        addLog("SUCCESS: File Sealed & Stored.");
        fetchFiles();
      }, 1000);
    } catch (err) {
      setUploadStep(0);
      addLog("ERROR: Upload Failed.");
      setError("Upload Failed. Check backend.");
    }
  };

  const handleDownload = async (file) => {
    if (file.mode !== 'hybrid') {
        setError("BASELINE ERROR: Baseline files are for performance benchmarking only. Cannot decrypt without PQC.");
        return;
    }

    try {
      addLog(`REQ: Access Request for File: ${file.filename}`);
      await downloadFile(file.id, file.filename);
      addLog("SUCCESS: Decrypted & Verified.");
    } catch (err) {
      addLog("❌ FAILURE: Decryption Aborted.");
      setError("CRITICAL: Integrity Tag Mismatch. File Modified.");
    }
  };

  return (
    <div className="p-8 space-y-6">
      
      {/* HEADER */}
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">Secure Gateway</h2>
          <p className="text-gray-400 text-sm">Post-Quantum Cryptography Enabled</p>
        </div>
        <div className="flex gap-4">
            <div className="flex flex-col items-end">
            <label className="text-[10px] text-gray-500 uppercase mb-1">Experiment Mode</label>
            <select 
                value={cryptoMode} 
                onChange={(e) => setCryptoMode(e.target.value)}
                className="bg-scifi-panel border border-scifi-border text-xs text-neon-blue p-2 rounded focus:outline-none"
            >
                <option value="hybrid">Hybrid (PQC + AES)</option>
                <option value="rsa">RSA-2048 (Baseline)</option>
            </select>
          </div>
        </div>
      </div>

      {error && (
        <div className="bg-red-900/20 border border-red-500 p-4 rounded text-red-500 font-bold">{error}</div>
      )}

      <div className="grid grid-cols-3 gap-6">
        
        {/* LEFT: UPLOAD & LOGS */}
        <div className="col-span-2 space-y-6">
            <div className="bg-scifi-panel border border-scifi-border rounded-xl p-6">
                <h3 className="text-white font-bold mb-4 flex items-center gap-2"><Upload size={18} /> Secure Upload</h3>
                {uploadStep > 0 ? (
                 <CryptoFlow currentStep={uploadStep} />
                ) : (
                <div className="border-2 border-dashed border-gray-700 rounded-lg p-10 text-center hover:border-neon-green transition-colors cursor-pointer relative">
                    <input type="file" onChange={handleUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                    <p className="text-white font-bold">Drop files here to encrypt</p>
                </div>
                )}
            </div>

            <div className="bg-black border border-gray-800 rounded-xl p-4 h-48 overflow-y-auto font-mono text-xs">
                <div className="flex items-center gap-2 text-gray-500 border-b border-gray-800 pb-2 mb-2">
                    <Terminal size={14} /> CRYPTO_KERNEL_LOGS
                </div>
                {logs.map((log, i) => <p key={i} className="text-neon-green/80 mb-1">{log}</p>)}
            </div>
            
            {/* NEW: SINGLE FILE REPORT */}
            {selectedFile && (
                <div className="bg-scifi-panel border border-neon-blue/30 rounded-xl p-4 animate-pulse-fast">
                    <h4 className="text-neon-blue font-bold mb-2 flex items-center gap-2">
                        <Activity size={16} /> Performance Report: {selectedFile.filename}
                    </h4>
                    <div className="grid grid-cols-3 gap-4 text-center">
                        <div className="bg-black/40 p-2 rounded">
                            <p className="text-xs text-gray-500">PQC Encap</p>
                            <p className="text-xl font-mono text-white">{selectedFile.metrics.pqc.toFixed(2)} ms</p>
                        </div>
                        <div className="bg-black/40 p-2 rounded">
                            <p className="text-xs text-gray-500">AES Encrypt</p>
                            <p className="text-xl font-mono text-white">{selectedFile.metrics.aes.toFixed(2)} ms</p>
                        </div>
                        <div className="bg-black/40 p-2 rounded">
                            <p className="text-xs text-gray-500">Total Latency</p>
                            <p className="text-xl font-mono text-white">{selectedFile.metrics.total.toFixed(2)} ms</p>
                        </div>
                    </div>
                </div>
            )}
        </div>

        {/* RIGHT: FILE LIST */}
        <div className="col-span-1 bg-scifi-panel border border-scifi-border rounded-xl p-6">
            <h3 className="text-white font-bold mb-4">Vault Contents</h3>
            <div className="space-y-2 max-h-[500px] overflow-y-auto custom-scrollbar">
                {files.map(file => (
                    <div 
                        key={file.id} 
                        onClick={() => setSelectedFile(file)} // Click to view stats
                        className={`p-3 rounded border transition cursor-pointer group relative
                            ${selectedFile?.id === file.id ? 'bg-neon-blue/10 border-neon-blue' : 'bg-white/5 border-transparent hover:border-gray-600'}`}
                    >
                        <div className="flex justify-between items-start">
                            <p className="text-xs text-white truncate w-32 font-bold">{file.filename}</p>
                            <span className={`text-[10px] px-1 rounded ${file.mode === 'hybrid' ? 'text-neon-green bg-neon-green/20' : 'text-neon-purple bg-neon-purple/20'}`}>
                                {file.mode === 'hybrid' ? 'PQC' : 'RSA'}
                            </span>
                        </div>
                        
                        {/* Action Buttons */}
                        <div className="flex justify-end items-center mt-2 gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                             <button onClick={(e) => { e.stopPropagation(); handleDelete(file.id); }} className="text-red-500 hover:text-white">
                                <Trash2 size={14} />
                            </button>
                            <button onClick={(e) => { e.stopPropagation(); handleDownload(file); }} className="text-neon-blue hover:text-white">
                                <Download size={14} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;
